function slicesWithAllThree(s: string): number {
  const n = s.length;
  let count = 0;
  for (let i = 0; i < n; i++) {
    const seen = new Set<string>();
    for (let j = i; j < n; j++) {
      seen.add(s[j]);
      if (seen.size === 3) { count += n - j; break; }
    }
  }
  return count;
}

