function slicesWithAllThree(s: string): number {
  const last = [-1, -1, -1];
  let count = 0;
  for (let r = 0; r < s.length; r++) {
    last[s.charCodeAt(r) - 97] = r;
    count += Math.min(last[0], last[1], last[2]) + 1;
  }
  return count;
}

